package com.kissene3.gui.interfaces;

import org.jetbrains.annotations.NotNull;

import java.awt.event.MouseEvent;

/** Interface that must be implemented by components that handles mouse's buttons' inputs. */
public interface Clickable {
	
	/**
	 * The method called when the component is clicked (pressed and then released).
	 * @param e The {@link MouseEvent} generated by the click.
	 */
	void onClick(@NotNull MouseEvent e);
	
	/**
	 * The method called when the component is pressed.
	 * @param e The {@link MouseEvent} generated by the press.
	 */
	void onPress(@NotNull MouseEvent e);
	
	/**
	 * The method called when the component is released.
	 * @param e The {@link MouseEvent} generated by the release.
	 */
	void onRelease(@NotNull MouseEvent e);
}
